# JS formatting/conversion
def is_undef(v): return v is undefined
def is_null(v): return v is null

def to_bool(v):
    if v is undefined or v is null: return False
    if isinstance(v,bool): return v
    if isinstance(v,(int,float)): return v != 0 and not (isinstance(v,float) and math.isnan(v))
    if isinstance(v,str): return len(v)>0
    return True

def to_number(v):
    if v is undefined: return float('nan')
    if v is null: return 0
    if isinstance(v,bool): return 1 if v else 0
    if isinstance(v,JSBigInt): return v.value
    if isinstance(v,(int,float)): return v
    if isinstance(v,str):
        s=v.strip()
        if s=='': return 0
        try: return int(s,0) if re.fullmatch(r'[+-]?0[xX][0-9a-fA-F]+',s) else float(s)
        except Exception: return float('nan')
    return float('nan')

def to_string(v):
    if v is undefined: return 'undefined'
    if v is null: return 'null'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,JSBigInt): return str(v.value)
    if isinstance(v,(int,float)): return num_to_str(v)
    if isinstance(v,str): return v
    if isinstance(v,JSArray): return ','.join('' if (x is undefined or x is null) else to_string(x) for x in v.items)
    return '[object Object]'

def num_to_str(x):
    if isinstance(x,bool): return 'true' if x else 'false'
    if isinstance(x,int): return str(x)
    if math.isnan(x): return 'NaN'
    if math.isinf(x): return 'Infinity' if x>0 else '-Infinity'
    if x == 0: return '0'
    if float(x).is_integer(): return str(int(x))
    return (('%g' % x).replace('e+','e'))

def js_repr(v, seen=None):
    if seen is None: seen=set()
    if v is undefined: return 'undefined'
    if v is null: return 'null'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,JSBigInt): return str(v.value)+'n'
    if isinstance(v,JSSymbol): return f"Symbol({v.desc})"
    if isinstance(v,(int,float)): return num_to_str(v)
    if isinstance(v,str): return v
    if isinstance(v,JSFunction): return '[Function%s]' % ((' '+v.name) if v.name else '')
    if isinstance(v,JSArray):
        if id(v) in seen: return '[Circular]'
        seen.add(id(v))
        return '[ ' + ', '.join(js_repr(x,seen) for x in v.items) + ' ]'
    if isinstance(v,JSObject):
        if v.class_name=='Error': return f"{v.get('name')}: {v.get('message')}"
        if id(v) in seen: return '[Circular]'
        seen.add(id(v))
        parts=[]
        for k,val in v.props.items():
            if isinstance(val,JSFunction): continue
            parts.append(f"{k}: {js_repr(val,seen)}")
        return '{ ' + ', '.join(parts) + ' }'
    return str(v)

def json_conv(v):
    if v is undefined or isinstance(v,JSFunction) or isinstance(v,JSSymbol):
        return None
    if v is null: return None
    if isinstance(v,bool) or isinstance(v,str): return v
    if isinstance(v,JSBigInt): raise JSError('TypeError','bigint are forbidden in JSON.stringify')
    if isinstance(v,(int,float)):
        if isinstance(v,float) and (math.isnan(v) or math.isinf(v)): return None
        return v
    if isinstance(v,JSArray): return [json_conv(x) for x in v.items]
    if isinstance(v,JSObject): return {k: json_conv(val) for k,val in v.props.items() if not isinstance(val,JSFunction) and val is not undefined}
    return v

