def string_method(s,name):
    def nf(fn,nm): return JSFunction(name=nm,native=lambda args,this: fn(args))
    if name=='toString': return nf(lambda args:s,'toString')
    if name=='trim': return nf(lambda args:s.strip(),'trim')
    if name=='toUpperCase': return nf(lambda args:s.upper(),'toUpperCase')
    if name=='toLowerCase': return nf(lambda args:s.lower(),'toLowerCase')
    if name=='includes': return nf(lambda args: to_string(args[0]) in s,'includes')
    if name=='startsWith': return nf(lambda args: s.startswith(to_string(args[0])),'startsWith')
    if name=='endsWith': return nf(lambda args: s.endswith(to_string(args[0])),'endsWith')
    if name=='indexOf': return nf(lambda args: s.find(to_string(args[0])),'indexOf')
    if name=='slice' or name=='substring':
        return nf(lambda args: s[int(to_number(args[0])) if args else 0:(int(to_number(args[1])) if len(args)>1 and args[1] is not undefined else None)], name)
    if name=='split': return nf(lambda args: JSArray(s.split(to_string(args[0]) if args else ',')),'split')
    if name=='replace': return nf(lambda args: s.replace(to_string(args[0]), to_string(args[1]) if len(args)>1 else '', 1),'replace')
    return undefined

def primitive_method(x,name):
    if name=='toString': return JSFunction(name='toString',native=lambda args,this: to_string(x))
    if name=='valueOf': return JSFunction(name='valueOf',native=lambda args,this: x)
    return undefined

def call_func(fn,args,this_arg=undefined):
    if not isinstance(fn,JSFunction): raise JSError('TypeError','not a function')
    return fn.call(args,this_arg)

def js_eq(a,b,strict=False):
    if strict:
        if (a is undefined and b is undefined) or (a is null and b is null): return True
        if type(a)!=type(b) and not (isinstance(a,(int,float)) and isinstance(b,(int,float))): return False
        return a==b
    if (a is undefined and b is null) or (a is null and b is undefined): return True
    if isinstance(a,bool): return js_eq(to_number(a),b,False)
    if isinstance(b,bool): return js_eq(a,to_number(b),False)
    if isinstance(a,str) and isinstance(b,(int,float)): return js_eq(to_number(a),b,False)
    if isinstance(b,str) and isinstance(a,(int,float)): return js_eq(a,to_number(b),False)
    return js_eq(a,b,True)

def js_add(a,b):
    if isinstance(a,JSBigInt) or isinstance(b,JSBigInt): return JSBigInt(to_number(a)+to_number(b))
    if isinstance(a,str) or isinstance(b,str): return to_string(a)+to_string(b)
    return to_number(a)+to_number(b)

def js_rel(a,b,op):
    if isinstance(a,str) and isinstance(b,str): av=a; bv=b
    else: av=to_number(a); bv=to_number(b)
    if op=='<': return av < bv
    if op=='>': return av > bv
    if op=='<=': return av <= bv
    return av >= bv

class Parser:
    def __init__(self, src_or_tokens, env, filename='<eval>', from_tokens=False, base_dir=None):
        self.tokens = list(src_or_tokens) if from_tokens else lex(src_or_tokens)
        if self.tokens and self.tokens[-1].typ!='EOF': self.tokens.append(Token('EOF',''))
        self.i=0; self.env=env; self.filename=filename; self.base_dir=base_dir or pyos.getcwd()
    def cur(self): return self.tokens[self.i]
    def peek(self,n=1): return self.tokens[self.i+n] if self.i+n < len(self.tokens) else Token('EOF','')
    def at(self,val=None,typ=None):
        t=self.cur(); return (val is None or t.val==val) and (typ is None or t.typ==typ)
    def eat(self,val=None,typ=None):
        if self.at(val,typ): t=self.cur(); self.i+=1; return t
        return None
    def expect(self,val=None,typ=None):
        t=self.eat(val,typ)
        if not t: raise JSError('SyntaxError', f"expecting '{val or typ}'", self.cur().line, self.cur().col)
        return t
    def parse_program(self):
        res=undefined
        while not self.at('', 'EOF') and not self.at('}'):
            if self.eat(';'): continue
            res=self.parse_statement(True)
        return res
    def parse_statement(self, active=True):
        t=self.cur()
        if not active:
            return self.skip_statement()
        if self.eat('{'):
            res=undefined
            while not self.at('}') and not self.at('', 'EOF'):
                res=self.parse_statement(True)
            self.expect('}'); return res
        if t.typ=='KW':
            kw=t.val
            if kw in ('let','const','var'): return self.parse_var_decl(self.eat().val)
            if kw=='function': return self.parse_func_decl()
            if kw=='return':
                self.eat(); val=undefined if self.at(';') or self.at('}') else self.parse_expression(); self.eat(';'); raise JSReturn(val)
            if kw=='throw':
                self.eat(); val=self.parse_expression(); self.eat(';')
                if isinstance(val,JSObject) and val.class_name=='Error': raise JSError(val.get('name'), val.get('message'))
                if isinstance(val,JSError): raise val
                raise JSError('Error', to_string(val))
            if kw=='if': return self.parse_if()
            if kw=='for': return self.parse_for()
            if kw=='while': return self.parse_while()
            if kw=='break': self.eat(); self.eat(';'); raise JSBreak()
            if kw=='continue': self.eat(); self.eat(';'); raise JSContinue()
            if kw=='try': return self.parse_try()
            if kw=='import': return self.parse_import()
            if kw=='export':
                self.eat()
                if self.at('default'):
                    self.eat(); val=self.parse_expression(); self.env.define('default',val); self.eat(';'); return val
                return self.parse_statement(True)
        val=self.parse_expression(); self.eat(';'); return val
    def skip_statement(self):
        if self.eat('{'):
            depth=1
            while depth and not self.at('', 'EOF'):
                if self.eat('{'): depth+=1
                elif self.eat('}'): depth-=1
                else: self.i+=1
            return undefined
        depth=0
        while not self.at('', 'EOF'):
            if self.at('{') or self.at('(') or self.at('['): depth+=1
            elif self.at('}') or self.at(')') or self.at(']'):
                if depth==0: break
                depth-=1
            if depth==0 and self.at(';'):
                self.i+=1; break
            if depth==0 and self.at('else'): break
            self.i+=1
        return undefined
    def parse_var_decl(self, kind):
        res=undefined
        while True:
            name=self.expect(typ='ID').val
            val=undefined
            if self.eat('='): val=self.parse_expression()
            self.env.define(name,val,const=(kind=='const'))
            res=val
            if not self.eat(','): break
        self.eat(';'); return res
    def parse_func_decl(self):
        self.expect('function','KW'); name=self.expect(typ='ID').val
        fn=self.parse_function_body(name)
        self.env.define(name,fn); return fn
    def parse_function_body(self,name='', arrow=False, params=None, expr_body=False):
        if params is None:
            self.expect('('); params=[]
            if not self.at(')'):
                while True:
                    params.append(self.expect(typ='ID').val)
                    if not self.eat(','): break
            self.expect(')')
        if expr_body:
            # collect expression tokens until comma/semicolon at top level
            start=self.i; depth=0
            while not self.at('', 'EOF'):
                if depth==0 and self.at(';'): break
                if self.at('(') or self.at('[') or self.at('{'): depth+=1
                elif self.at(')') or self.at(']') or self.at('}'):
                    if depth==0: break
                    depth-=1
                self.i+=1
            body=self.tokens[start:self.i]+[Token('EOF','')]
            return JSFunction(params, body, self.env, name, arrow=arrow, expr_body=True, this_value=self.env.vars.get('this',undefined))
        self.expect('{'); body=self.collect_until_matching('{','}')
        return JSFunction(params, body+[Token('EOF','')], self.env, name, arrow=arrow, this_value=self.env.vars.get('this',undefined))
    def collect_until_matching(self,openv,closev):
        depth=1; start=self.i
        while depth and not self.at('', 'EOF'):
            if self.at(openv): depth+=1
            elif self.at(closev):
                depth-=1
                if depth==0:
                    body=self.tokens[start:self.i]; self.i+=1; return body
            self.i+=1
        return self.tokens[start:self.i]
    def collect_paren_tokens(self):
        self.expect('('); depth=1; start=self.i
        while depth and not self.at('', 'EOF'):
            if self.at('('): depth+=1
            elif self.at(')'):
                depth-=1
                if depth==0:
                    toks=self.tokens[start:self.i]; self.i+=1; return toks
            self.i+=1
        return []
    def collect_statement_tokens(self):
        if self.at('{'):
            self.eat('{'); return self.collect_until_matching('{','}')+[Token('EOF','')]
        start=self.i; depth=0
        while not self.at('', 'EOF'):
            if self.at('(') or self.at('[') or self.at('{'): depth+=1
            elif self.at(')') or self.at(']') or self.at('}'):
                if depth==0: break
                depth-=1
            if depth==0 and self.at(';'):
                self.i+=1; break
            self.i+=1
        return self.tokens[start:self.i]+[Token('EOF','')]
    def sub_eval(self,toks, default=undefined):
        if not toks: return default
        p=Parser(toks+[Token('EOF','')], self.env, self.filename, from_tokens=True, base_dir=self.base_dir)
        return p.parse_statement(True) if (toks and toks[0].val in ('let','const','var')) else p.parse_expression()
    def parse_if(self):
        self.expect('if','KW'); cond_toks=self.collect_paren_tokens(); cond=Parser(cond_toks+[Token('EOF','')], self.env, self.filename, True, self.base_dir).parse_expression()
        if to_bool(cond):
            res=self.parse_statement(True)
            if self.eat('else','KW'): self.parse_statement(False)
            return res
        else:
            self.parse_statement(False)
            if self.eat('else','KW'): return self.parse_statement(True)
            return undefined
    def parse_for(self):
        self.expect('for','KW'); self.expect('(')
        # for..of rudimentary
        start=self.i; depth=0; semi=[]
        while not self.at('', 'EOF'):
            if depth==0 and self.at(')'): break
            if depth==0 and self.at(';'): semi.append(self.i)
            if self.at('(') or self.at('[') or self.at('{'): depth+=1
            elif self.at(')') or self.at(']') or self.at('}'): depth-=1
            self.i+=1
        end=self.i; self.expect(')')
        header=self.tokens[start:end]
        body=self.collect_statement_tokens()
        # detect for (let x of arr)
        vals=[t.val for t in header]
        if 'of' in vals:
            oi=vals.index('of'); varname=header[oi-1].val; expr_toks=header[oi+1:]
            iterable=Parser(expr_toks+[Token('EOF','')], self.env, self.filename, True, self.base_dir).parse_expression()
            items=iterable.items if isinstance(iterable,JSArray) else list(to_string(iterable))
            res=undefined
            for item in items:
                if not self.env.has_local(varname): self.env.define(varname,item)
                else: self.env.set(varname,item)
                try: res=Parser(body, self.env, self.filename, True, self.base_dir).parse_program()
                except JSContinue: continue
                except JSBreak: break
            return res
        # split header by semis
        parts=[]; last=0; depth=0
        for idx,tok in enumerate(header):
            if tok.val in '([{': depth+=1
            elif tok.val in ')]}': depth-=1
            elif tok.val==';' and depth==0:
                parts.append(header[last:idx]); last=idx+1
        parts.append(header[last:])
        while len(parts)<3: parts.append([])
        if parts[0]: self.sub_eval(parts[0])
        res=undefined; guard=0
        while True:
            if parts[1] and not to_bool(Parser(parts[1]+[Token('EOF','')], self.env, self.filename, True, self.base_dir).parse_expression()): break
            try: res=Parser(body, self.env, self.filename, True, self.base_dir).parse_program()
            except JSContinue: pass
            except JSBreak: break
            if parts[2]: Parser(parts[2]+[Token('EOF','')], self.env, self.filename, True, self.base_dir).parse_expression()
            guard+=1
            if guard>100000: raise JSError('InternalError','loop limit exceeded')
        return res
    def parse_while(self):
        self.expect('while','KW'); cond_toks=self.collect_paren_tokens(); body=self.collect_statement_tokens(); res=undefined; guard=0
        while to_bool(Parser(cond_toks+[Token('EOF','')], self.env, self.filename, True, self.base_dir).parse_expression()):
            try: res=Parser(body, self.env, self.filename, True, self.base_dir).parse_program()
            except JSContinue: pass
            except JSBreak: break
            guard+=1
            if guard>100000: raise JSError('InternalError','loop limit exceeded')
        return res
    def parse_try(self):
        self.expect('try','KW')
        self.expect('{'); try_body=self.collect_until_matching('{','}')+[Token('EOF','')]
        catch_name=None; catch_body=None; finally_body=None
        if self.eat('catch','KW'):
            if self.eat('('): catch_name=self.expect(typ='ID').val; self.expect(')')
            self.expect('{'); catch_body=self.collect_until_matching('{','}')+[Token('EOF','')]
        if self.eat('finally','KW'):
            self.expect('{'); finally_body=self.collect_until_matching('{','}')+[Token('EOF','')]
        res=undefined
        try:
            res=Parser(try_body,self.env,self.filename,True,self.base_dir).parse_program()
        except JSError as e:
            if catch_body is None: raise
            cenv=Env(self.env)
            if catch_name:
                cenv.define(catch_name, JSObject({'name':e.name,'message':e.message}, class_name='Error'))
            res=Parser(catch_body,cenv,self.filename,True,self.base_dir).parse_program()
        finally:
            if finally_body: Parser(finally_body,self.env,self.filename,True,self.base_dir).parse_program()
        return res
    def parse_import(self):
        self.expect('import','KW')
        # import("x") as expression is handled elsewhere poorly
        if self.cur().typ=='STRING':
            path=self.eat(typ='STRING').val; self.eat(';'); self.load_module(path); return undefined
        names=[]; nsname=None
        if self.eat('*','OP'):
            self.expect('as','KW'); nsname=self.expect(typ='ID').val
        elif self.eat('{'):
            while not self.at('}'):
                orig=self.expect(typ='ID').val; local=orig
                if self.eat('as','KW'): local=self.expect(typ='ID').val
                names.append((orig,local))
                self.eat(',')
            self.expect('}')
        elif self.cur().typ=='ID':
            names.append(('default', self.eat().val))
        self.expect('from','KW'); path=self.expect(typ='STRING').val; self.eat(';')
        mod=self.load_module(path)
        if nsname: self.env.define(nsname, mod)
        for orig,local in names: self.env.define(local, get_prop(mod,orig))
        return undefined
    def load_module(self,path):
        if path in ('std','os'):
            return self.env.root().get(path)
        full=path
        if not pyos.path.isabs(full): full=pyos.path.normpath(pyos.path.join(self.base_dir,path))
        if full in module_cache: return module_cache[full]
        try:
            src=open(full,'r',encoding='utf-8').read()
        except Exception as e: raise JSError('Error', f"could not load module filename '{path}'")
        menv=Env(self.env.root(), strict=True)
        install_builtins(menv, [], True)
        p=Parser(src,menv,full,False,pyos.path.dirname(full)); p.parse_program()
        obj=JSObject({k:v for k,v in menv.vars.items() if not k.startswith('__')})
        module_cache[full]=obj; return obj

    # expression parser
    def parse_expression(self): return self.parse_comma()
    def parse_comma(self):
        v=self.parse_assignment()
        while self.eat(','): v=self.parse_assignment()
        return v
    def parse_assignment(self):
        # arrow: id => expr/body
        if self.cur().typ=='ID' and self.peek().val=='=>':
            name=self.eat().val; self.eat('=>','OP')
            if self.at('{'):
                self.eat('{'); body=self.collect_until_matching('{','}')+[Token('EOF','')]
                return JSFunction([name],body,self.env,arrow=True,this_value=self.env.vars.get('this',undefined))
            return self.parse_function_body('', True, [name], expr_body=True)
        left=self.parse_conditional(ref=True)
        if self.cur().val in ('=','+=','-=','*=','/=','%='):
            op=self.eat().val; rhs=self.parse_assignment(); curv=left.get() if isinstance(left,Reference) else left
            if op=='=': val=rhs
            elif op=='+=': val=js_add(curv,rhs)
            elif op=='-=': val=to_number(curv)-to_number(rhs)
            elif op=='*=': val=to_number(curv)*to_number(rhs)
            elif op=='/=': val=to_number(curv)/to_number(rhs)
            else: val=to_number(curv)%to_number(rhs)
            if isinstance(left,Reference): return left.set(val)
            raise JSError('ReferenceError','invalid assignment left-hand side')
        return left.get() if isinstance(left,Reference) else left
    def parse_conditional(self, ref=False):
        v=self.parse_logical_or(ref=ref)
        if self.eat('?'):
            tv=self.parse_expression(); self.expect(':'); fv=self.parse_assignment()
            return tv if to_bool(v.get() if isinstance(v,Reference) else v) else fv
        return v
    def parse_logical_or(self, ref=False):
        v=self.parse_logical_and(ref=ref)
        while self.cur().val in ('||','??'):
            op=self.eat().val; val=v.get() if isinstance(v,Reference) else v
            if op=='||':
                if to_bool(val): v=val; self.parse_logical_and(); continue
                v=self.parse_logical_and()
            else:
                if val is not undefined and val is not null: v=val; self.parse_logical_and(); continue
                v=self.parse_logical_and()
        return v
    def parse_logical_and(self, ref=False):
        v=self.parse_equality(ref=ref)
        while self.eat('&&','OP'):
            val=v.get() if isinstance(v,Reference) else v
            if not to_bool(val): v=val; self.parse_equality(); continue
            v=self.parse_equality()
        return v
    def parse_equality(self, ref=False):
        v=self.parse_relational(ref=ref)
        while self.cur().val in ('==','!=','===','!=='):
            op=self.eat().val; r=self.parse_relational(); av=v.get() if isinstance(v,Reference) else v
            v=js_eq(av,r,op in ('===','!=='))
            if op in ('!=','!=='): v=not v
        return v
    def parse_relational(self, ref=False):
        v=self.parse_additive(ref=ref)
        while self.cur().val in ('<','>','<=','>=','in'):
            op=self.eat().val; r=self.parse_additive(); av=v.get() if isinstance(v,Reference) else v
            if op=='in': v=isinstance(r,(JSObject,JSArray)) and (str(av) in (r.props if isinstance(r,JSObject) else {}))
            else: v=js_rel(av,r,op)
        return v
    def parse_additive(self, ref=False):
        v=self.parse_multiplicative(ref=ref)
        while self.cur().val in ('+','-'):
            op=self.eat().val; r=self.parse_multiplicative(); av=v.get() if isinstance(v,Reference) else v
            v=js_add(av,r) if op=='+' else to_number(av)-to_number(r)
        return v
    def parse_multiplicative(self, ref=False):
        v=self.parse_power(ref=ref)
        while self.cur().val in ('*','/','%'):
            op=self.eat().val; r=self.parse_power(); av=v.get() if isinstance(v,Reference) else v
            if op=='*': v=to_number(av)*to_number(r)
            elif op=='/':
                try: v=to_number(av)/to_number(r)
                except ZeroDivisionError: v=float('inf') if to_number(av)>=0 else float('-inf')
            else: v=to_number(av)%to_number(r)
        return v
    def parse_power(self, ref=False):
        v=self.parse_unary(ref=ref)
        if self.eat('**','OP'):
            r=self.parse_power(); av=v.get() if isinstance(v,Reference) else v; return to_number(av)**to_number(r)
        return v
    def parse_unary(self, ref=False):
        if self.cur().val in ('!','+','-','~') or (self.cur().typ=='KW' and self.cur().val in ('typeof','void','delete','new')):
            op=self.eat().val
            if op=='new':
                ctor=self.parse_unary(); args=[]
                if self.eat('('):
                    if not self.at(')'):
                        while True:
                            args.append(self.parse_assignment())
                            if not self.eat(','): break
                    self.expect(')')
                return construct(ctor,args)
            if op=='typeof':
                try: v=self.parse_unary()
                except JSError as e:
                    if e.name=='ReferenceError': return 'undefined'
                    raise
                return js_typeof(v.get() if isinstance(v,Reference) else v)
            if op=='void': self.parse_unary(); return undefined
            if op=='delete':
                v=self.parse_unary(ref=True)
                if isinstance(v,Reference) and v.obj is not None and isinstance(v.obj,JSObject): v.obj.props.pop(str(v.key),None)
                return True
            v=self.parse_unary(); val=v.get() if isinstance(v,Reference) else v
            if op=='!': return not to_bool(val)
            if op=='+': return to_number(val)
            if op=='-': return -to_number(val)
            return int(to_number(val)) ^ -1
        if self.cur().val in ('++','--'):
            op=self.eat().val; r=self.parse_unary(ref=True)
            if not isinstance(r,Reference): raise JSError('ReferenceError','invalid increment operand')
            val=to_number(r.get())+(1 if op=='++' else -1); r.set(val); return val
        return self.parse_postfix(ref=ref)
    def parse_postfix(self, ref=False):
        v=self.parse_primary(ref=True)
        while True:
            if self.eat('.'):
                key=self.expect(typ='ID').val if self.cur().typ in ('ID','KW') else self.expect().val
                obj=v.get() if isinstance(v,Reference) else v
                v=Reference(obj=obj,key=key)
            elif self.eat('['):
                key=self.parse_expression(); self.expect(']'); obj=v.get() if isinstance(v,Reference) else v; v=Reference(obj=obj,key=key)
            elif self.eat('('):
                args=[]
                if not self.at(')'):
                    while True:
                        args.append(self.parse_assignment())
                        if not self.eat(','): break
                self.expect(')')
                if isinstance(v,Reference):
                    fn=v.get(); this_arg=v.obj if v.obj is not None else undefined
                else: fn=v; this_arg=undefined
                v=call_func(fn,args,this_arg)
            elif self.cur().val in ('++','--'):
                op=self.eat().val
                if not isinstance(v,Reference): raise JSError('ReferenceError','invalid increment operand')
                old=v.get(); v.set(to_number(old)+(1 if op=='++' else -1)); v=old
            else: break
        return v if ref else (v.get() if isinstance(v,Reference) else v)
    def parse_primary(self, ref=False):
        t=self.cur()
        if self.eat('('):
            # arrow with parenthesized parameter list: already consumed (, look for )=>
            save=self.i; params=[]; ok=True
            if not self.at(')'):
                while True:
                    if self.cur().typ!='ID': ok=False; break
                    params.append(self.eat().val)
                    if not self.eat(','): break
            if ok and self.eat(')') and self.eat('=>','OP'):
                if self.at('{'):
                    self.eat('{'); body=self.collect_until_matching('{','}')+[Token('EOF','')]
                    return JSFunction(params,body,self.env,arrow=True,this_value=self.env.vars.get('this',undefined))
                return self.parse_function_body('', True, params, expr_body=True)
            self.i=save
            v=self.parse_expression(); self.expect(')'); return v
        if t.typ=='NUMBER': self.i+=1; return t.val
        if t.typ=='BIGINT': self.i+=1; return JSBigInt(t.val)
        if t.typ=='STRING': self.i+=1; return t.val
        if t.typ=='ID': self.i+=1; return Reference(env=self.env,name=t.val) if ref else self.env.get(t.val)
        if t.typ=='KW':
            if t.val=='true': self.i+=1; return True
            if t.val=='false': self.i+=1; return False
            if t.val=='null': self.i+=1; return null
            if t.val=='undefined': self.i+=1; return undefined
            if t.val=='this': self.i+=1; return self.env.vars.get('this', self.env.root().vars.get('globalThis',undefined))
            if t.val=='function':
                self.i+=1; name=''
                if self.cur().typ=='ID': name=self.eat().val
                return self.parse_function_body(name)
        if self.eat('['):
            items=[]
            if not self.at(']'):
                while True:
                    if self.at(','): items.append(undefined); self.eat(','); continue
                    items.append(self.parse_assignment())
                    if not self.eat(','): break
                    if self.at(']'): break
            self.expect(']'); return JSArray(items)
        if self.eat('{'):
            obj=JSObject()
            if not self.at('}'):
                while True:
                    if self.cur().typ in ('ID','KW','STRING','NUMBER'):
                        key=str(self.eat().val)
                    else: key=str(self.expect().val)
                    if self.eat(':'): val=self.parse_assignment()
                    elif self.eat('('):
                        # method syntax skipped
                        params=[]
                        if not self.at(')'):
                            while True:
                                params.append(self.expect(typ='ID').val)
                                if not self.eat(','): break
                        self.expect(')'); self.expect('{'); body=self.collect_until_matching('{','}')+[Token('EOF','')]
                        val=JSFunction(params,body,self.env,name=key)
                    else: val=self.env.get(key)
                    obj.set(key,val)
                    if not self.eat(','): break
                    if self.at('}'): break
            self.expect('}'); return obj
        raise JSError('SyntaxError', f"unexpected token '{t.val}'", t.line,t.col)

module_cache={}

def js_typeof(v):
    if v is undefined: return 'undefined'
    if v is null: return 'object'
    if isinstance(v,bool): return 'boolean'
    if isinstance(v,(int,float)): return 'number'
    if isinstance(v,JSBigInt): return 'bigint'
    if isinstance(v,str): return 'string'
    if isinstance(v,JSSymbol): return 'symbol'
    if isinstance(v,JSFunction): return 'function'
    return 'object'

def construct(ctor,args):
    # Error and Array constructors
    if isinstance(ctor,JSFunction) and ctor.name in ('Error','TypeError','ReferenceError','SyntaxError'):
        msg=to_string(args[0]) if args else ''
        return JSObject({'name':ctor.name,'message':msg}, class_name='Error')
    if isinstance(ctor,JSFunction) and ctor.name=='Array':
        if len(args)==1 and isinstance(args[0],(int,float)): return JSArray([undefined]*int(args[0]))
        return JSArray(args)
    if isinstance(ctor,JSFunction):
        obj=JSObject(class_name=ctor.name or 'Object')
        res=ctor.call(args,obj)
        return res if isinstance(res,JSObject) else obj
    raise JSError('TypeError','not a constructor')

def c_format(fmt,args):
    # A pragmatic subset of printf/sprintf formatting.
    vals=[]
    for a in args:
        if isinstance(a,(int,float)): vals.append(a)
        elif isinstance(a,JSBigInt): vals.append(a.value)
        else: vals.append(to_string(a))
    try:
        return fmt % tuple(vals)
    except Exception:
        # replace common specifiers one by one
        out=''; ai=0; i=0
        while i < len(fmt):
            if fmt[i]=='%' and i+1<len(fmt):
                j=i+1
                if fmt[j]=='%': out+='%'; i+=2; continue
                while j<len(fmt) and fmt[j] not in 'sdifFeEgGxXo': j+=1
                if j<len(fmt) and ai<len(args):
                    spec=fmt[i:j+1]; val=args[ai]; ai+=1
                    try: out += spec % (to_number(val) if spec[-1] in 'difFeEgGxXo' else to_string(val))
                    except Exception: out += to_string(val)
                    i=j+1; continue
            out+=fmt[i]; i+=1
        return out

def make_std(env):
    std=JSObject(class_name='Object')
    std.set('SEEK_SET',0); std.set('SEEK_CUR',1); std.set('SEEK_END',2); std.set('Error', env.get('Error'))
    std.set('puts', JSFunction(name='puts',native=lambda args,this: (sys.stdout.write(to_string(args[0] if args else '')+'\n'), sys.stdout.flush(), undefined)[2]))
    std.set('printf', JSFunction(name='printf',native=lambda args,this: (sys.stdout.write(c_format(to_string(args[0]) if args else '', args[1:])), sys.stdout.flush(), undefined)[2]))
    std.set('sprintf', JSFunction(name='sprintf',native=lambda args,this: c_format(to_string(args[0]) if args else '', args[1:])))
    std.set('getenv', JSFunction(name='getenv',native=lambda args,this: pyos.environ.get(to_string(args[0])) if args and to_string(args[0]) in pyos.environ else undefined))
    std.set('setenv', JSFunction(name='setenv',native=lambda args,this: (pyos.environ.__setitem__(to_string(args[0]),to_string(args[1]) if len(args)>1 else ''), undefined)[1]))
    std.set('unsetenv', JSFunction(name='unsetenv',native=lambda args,this: (pyos.environ.pop(to_string(args[0]),None), undefined)[1]))
    std.set('getenviron', JSFunction(name='getenviron',native=lambda args,this: JSObject(dict(pyos.environ))))
    std.set('exit', JSFunction(name='exit',native=lambda args,this: (_ for _ in ()).throw(SystemExit(int(to_number(args[0])) if args else 0))))
