            op=self.eat().val; rhs=self.parse_assignment(); curv=left.get() if isinstance(left,Reference) else left
            if op=='=': val=rhs
            elif op=='+=': val=js_add(curv,rhs)
            elif op=='-=': val=to_number(curv)-to_number(rhs)
            elif op=='*=': val=to_number(curv)*to_number(rhs)
            elif op=='/=': val=to_number(curv)/to_number(rhs)
            else: val=to_number(curv)%to_number(rhs)
            if isinstance(left,Reference): return left.set(val)
            raise JSError('ReferenceError','invalid assignment left-hand side')
