def os_exec(args):
    if not args: return -1
    if isinstance(args[0],JSArray): cmd=[to_string(x) for x in args[0].items]
    else: cmd=[to_string(args[0])]+[to_string(x) for x in args[1:]]
    try: return subprocess.call(cmd)
    except Exception: return -1

