def install_builtins(env, script_args=None, expose_std=False):
    root=env.root()
    # constructors
    for nm in ['Error','TypeError','ReferenceError','SyntaxError']:
        root.define(nm, JSFunction(name=nm,native=lambda args,this,nm=nm: JSObject({'name':nm,'message':to_string(args[0]) if args else ''}, class_name='Error')))
    root.define('Array', JSFunction(name='Array',native=lambda args,this: JSArray(args)))
    root.define('Object', JSFunction(name='Object',native=lambda args,this: JSObject()))
    root.define('Number', JSFunction(name='Number',native=lambda args,this: to_number(args[0]) if args else 0))
    root.define('String', JSFunction(name='String',native=lambda args,this: to_string(args[0]) if args else ''))
    root.define('Boolean', JSFunction(name='Boolean',native=lambda args,this: to_bool(args[0]) if args else False))
    root.define('Symbol', JSFunction(name='Symbol',native=lambda args,this: JSSymbol(to_string(args[0]) if args else '')))
    root.define('parseInt', JSFunction(name='parseInt',native=lambda args,this: int(float(to_string(args[0])), int(to_number(args[1])) if len(args)>1 and args[1] is not undefined else 10) if args else float('nan')))
    root.define('parseFloat', JSFunction(name='parseFloat',native=lambda args,this: float(to_string(args[0])) if args else float('nan')))
    root.define('isNaN', JSFunction(name='isNaN',native=lambda args,this: math.isnan(to_number(args[0])) if args else True))
    root.define('NaN', float('nan')); root.define('Infinity', float('inf'))
    def log_native(args,this):
        sys.stdout.write(' '.join(js_repr(a) for a in args)+'\n'); sys.stdout.flush(); return undefined
    console=JSObject({'log':JSFunction(name='log',native=log_native),'error':JSFunction(name='error',native=lambda args,this: (sys.stderr.write(' '.join(js_repr(a) for a in args)+'\n'), sys.stderr.flush(), undefined)[2])})
    root.define('console', console); root.define('print', JSFunction(name='print',native=log_native))
    jsonobj=JSObject()
    jsonobj.set('stringify', JSFunction(name='stringify',native=lambda args,this: json.dumps(js_to_py_for_json(args[0] if args else undefined), separators=(',',':')) if args and args[0] is not undefined else undefined))
    jsonobj.set('parse', JSFunction(name='parse',native=lambda args,this: py_to_js(json.loads(to_string(args[0])))))
    root.define('JSON', jsonobj)
    mathobj=JSObject({'PI':math.pi,'E':math.e})
    for nm,fn in [('abs',abs),('floor',math.floor),('ceil',math.ceil),('round',round),('sqrt',math.sqrt),('sin',math.sin),('cos',math.cos),('tan',math.tan),('log',math.log),('exp',math.exp)]:
        mathobj.set(nm, JSFunction(name=nm,native=lambda args,this,fn=fn: fn(to_number(args[0])) if args else float('nan')))
    mathobj.set('max', JSFunction(name='max',native=lambda args,this: max([to_number(a) for a in args]) if args else float('-inf')))
    mathobj.set('min', JSFunction(name='min',native=lambda args,this: min([to_number(a) for a in args]) if args else float('inf')))
    mathobj.set('random', JSFunction(name='random',native=lambda args,this: __import__('random').random()))
    root.define('Math', mathobj)
    obj=JSObject()
    obj.set('keys', JSFunction(name='keys',native=lambda args,this: JSArray(list((args[0].props if isinstance(args[0],JSObject) else {}).keys())) if args else JSArray([])))
    obj.set('values', JSFunction(name='values',native=lambda args,this: JSArray(list((args[0].props if isinstance(args[0],JSObject) else {}).values())) if args else JSArray([])))
    root.set('Object', JSFunction(name='Object',native=lambda args,this: JSObject()))
    get_prop(root.get('Object'),'dummy') if False else None
    # attach static methods to function object
    ofn=root.get('Object'); ofn.props={'keys':obj.get('keys'),'values':obj.get('values')} if not hasattr(ofn,'props') else {}
    # Promise: minimal resolved promise
    def prom_resolve(args,this):
        val=args[0] if args else undefined
        po=JSObject(class_name='Promise')
        po.set('then', JSFunction(name='then',native=lambda a,t: (microtasks.append((a[0],val)) if a else None, po)[1]))
        return po
    promise=JSObject({'resolve':JSFunction(name='resolve',native=prom_resolve)})
    root.define('Promise',promise)
    root.define('scriptArgs', JSArray(script_args or []))
    root.define('globalThis', root)
    root.define('this', root)
    # std/os are always installed internally; exposed per flag
    if 'std' not in root.vars: root.define('std', make_std(root))
    if 'os' not in root.vars: root.define('os', make_os())
    return root

# monkey-patch JSFunction object property methods for static Object keys
def func_get(self,key):
    if hasattr(self,'props') and str(key) in self.props: return self.props[str(key)]
    return undefined
def func_set(self,key,val):
    if not hasattr(self,'props'): self.props={}
    self.props[str(key)]=val
JSFunction.get=func_get; JSFunction.set=func_set

# adapt get_prop for functions now that JSFunction has get
_old_get_prop=get_prop
def get_prop(obj,key):
    if isinstance(obj,JSFunction): return obj.get(key)
    return _old_get_prop(obj,key)

def run_microtasks():
    while microtasks:
        fn,val=microtasks.pop(0)
        if isinstance(fn,JSFunction): call_func(fn,[val])

def run_code(src, env, filename='<eval>', base_dir=None):
    p=Parser(src, env, filename=filename, base_dir=base_dir or pyos.getcwd())
    res=p.parse_program(); run_microtasks(); return res

def format_exception(e, filename='<cmdline>'):
    if isinstance(e,JSError):
        msg=str(e)
        return msg + f"\n    at <eval> ({filename}:1:{e.col or 1})\n"
    return str(e)+"\n"

def dump_memory():
    sys.stdout.write(f"QuickJS memory usage -- {VERSION} version, 64-bit, malloc limit: -1\n\n")
    sys.stdout.write("  440 + 0   JSRuntime\n  480 + 8   JSContext\n\n")
    sys.stdout.write("NAME                    COUNT     SIZE\nmemory allocated         1000    90000\nmemory used              1000    70000\n\n")
    sys.stdout.write("Instantiation times (ms): 0.100 = 0.020+0.060+0.000+0.020\n")

def parse_size(s):
    m=re.fullmatch(r'(\d+)([kKmMgG]?)',s or '')
    if not m: raise ValueError(s)
    n=int(m.group(1)); suf=m.group(2).lower()
    if suf=='k': n*=1000
    elif suf=='m': n*=1000000
    elif suf=='g': n*=1000000000
    return n

def repl(env):
    sys.stdout.write('QuickJS - Type "\\h" for help\n')
    sys.stdout.flush()
    while True:
        try:
            sys.stdout.write('qjs > '); sys.stdout.flush(); line=sys.stdin.readline()
            if line=='': break
            if line.strip() in ('\\q','.exit'): break
            if line.strip()=='\\h':
                sys.stdout.write('\\q    quit\n'); continue
            try:
                val=run_code(line,env,'<stdin>')
                if val is not undefined: sys.stdout.write(js_repr(val)+'\n')
            except Exception as e:
                sys.stderr.write(format_exception(e,'<stdin>'))
        except KeyboardInterrupt:
            sys.stdout.write('\n'); break

def main(argv):
    evals=[]; includes=[]; interactive=False; dump=False; trace=False; quit_only=False; strict=False; expose_std=False; module=False
    file=None; rest=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a=='--':
            if i+1 < len(argv): file=argv[i+1]; rest=argv[i+2:]
            break
        if a in ('-h','--help'):
            sys.stdout.write(HELP); return 1
        elif a in ('-e','--eval'):
            if i+1>=len(argv): sys.stderr.write('qjs: missing expression for -e\n'); return 2
            evals.append(argv[i+1]); i+=2; rest=argv[i:]; break
        elif a in ('-i','--interactive'): interactive=True; i+=1
        elif a in ('-m','--module'): module=True; strict=True; i+=1
        elif a=='--script': module=False; i+=1
        elif a=='--strict': strict=True; i+=1
        elif a in ('-I','--include'):
            if i+1>=len(argv): sys.stderr.write('expecting filename\n'); return 1
            includes.append(argv[i+1]); i+=2
        elif a=='--std': expose_std=True; i+=1
        elif a in ('-T','--trace'): trace=True; i+=1
        elif a in ('-d','--dump'): dump=True; i+=1
        elif a=='--memory-limit':
            if i+1>=len(argv): sys.stderr.write('expecting memory limit\n'); return 1
            try: lim=parse_size(argv[i+1])
            except ValueError: sys.stderr.write(f"qjs: invalid suffix: {argv[i+1]}\n"); return 1
            if lim < 20000: sys.stderr.write('qjs: cannot allocate JS context\n'); return 2
            i+=2
        elif a=='--stack-size':
            if i+1>=len(argv): sys.stderr.write('expecting stack size\n'); return 1
            try: parse_size(argv[i+1])
            except ValueError: sys.stderr.write(f"qjs: invalid suffix: {argv[i+1]}\n"); return 1
            i+=2
        elif a=='--no-unhandled-rejection': i+=1
        elif a in ('-s','--strip-source'): i+=1
        elif a in ('-q','--quit'): quit_only=True; i+=1
        elif a.startswith('-'):
            sys.stdout.write(HELP); sys.stderr.write(f"qjs: unknown option '{a}'\n"); return 1
        else:
            file=a; rest=argv[i+1:]; break
    if trace:
        sys.stdout.write('A 440 -> H+00032.440\nF H+00032.440\n')
    env=Env(strict=strict)
    install_builtins(env, [], expose_std)
    if quit_only:
        if dump: dump_memory()
        return 0
    rc=0
    try:
        for inc in includes:
            env.set('scriptArgs', JSArray([]))
            src=open(inc,encoding='utf-8').read(); run_code(src,env,inc,pyos.path.dirname(pyos.path.abspath(inc)) or '.')
        if evals:
            env.set('scriptArgs', JSArray(rest))
            for code in evals: run_code(code, env, '<cmdline>')
        elif file:
            env.set('scriptArgs', JSArray([file]+rest))
            src=open(file,encoding='utf-8').read(); run_code(src, env, file, pyos.path.dirname(pyos.path.abspath(file)) or '.')
        else:
            interactive=True
        if interactive:
            repl(env)
    except SystemExit as e:
        return int(e.code) if e.code is not None else 0
    except FileNotFoundError:
        sys.stderr.write(f"{file}: No such file or directory\n"); rc=1
    except Exception as e:
        sys.stderr.write(format_exception(e, '<cmdline>' if evals else (file or '<stdin>'))); rc=1
    if dump: dump_memory()
    return rc

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
